async function loadConfig(){try{const o=await fetch(`${window.APP_CONFIG.api.baseURL}/api/config`);if(o.ok){const a=await o.json();window.APP_CONFIG.api.baseURL=`http://${a.apiHost}:${a.apiPort}`,console.log("Configuration loaded:",window.APP_CONFIG.api.baseURL)}}catch(o){console.warn("Could not load dynamic config, using defaults:",o.message)}}window.APP_CONFIG={api:{baseURL:"http://localhost:8080",timeouts:{default:1e4,upload:6e4},retry:{maxRetries:2,initialDelay:1e3}},features:{enableDebugLogging:!0,enableErrorReporting:!0,enableAnalytics:!1}},loadConfig(),console.log("Application configuration loaded:",window.APP_CONFIG);